"""Inventory and package complete growth sources after an explicit pre-timing freeze."""
import argparse
from datetime import datetime, timezone
import difflib
import gzip
import hashlib
import importlib.util
import io
import json
from pathlib import Path, PurePosixPath
import subprocess
import sys
import tarfile
import tempfile

ROOT = Path(__file__).resolve().parents[3]
PHASE = Path('result-coordinate-evidence/growth-followup')
OLD = Path('result-coordinate-evidence/admission-followup')
RETENTION = Path('result-coordinate-evidence/retention-followup')
ARTIFACTS = ROOT / PHASE / 'artifacts'
PACKAGE = Path('org/eclipse/rdf4j/sail/lmdb/evaluation')
PRODUCTION = Path('core/sail/lmdb/src/main/java') / PACKAGE
BASE_COMMIT = 'b8d2015ec1b722b71f9a8af9e50cd98558f7882a'
PREFIX = 'growth-complete-source-v1'
NAMES = ('NativeResultMaterializer', 'NativeProjectedBindingSet', 'NativeDirectValueMemo',
         'NativeDirectValueMemoStatistics')
JAVA_ROOTS = ('implementation-src', 'benchmark/src', 'diagnostics/src', 'contracts/test-src')
PYTHON_ROOTS = ('', 'benchmark', 'benchmark/checks', 'contracts', 'diagnostics',
                'diagnostics/analysis', 'reviews', 'formatting', 'recovery', 'artifacts')
PRIOR_ARCHIVE = OLD / 'artifacts/complete-source-v2.tar.gz'
PRIOR_ARCHIVE_SHA = '831feacaf27d260da3c8b0c53bd2503b1a4d9000b7f5662490a940d024d70bb0'
PRIOR_MANIFEST = OLD / 'artifacts/complete-source-v2.manifest.json'
PRIOR_MANIFEST_SHA = 'aad5fe02d19314075f8ee47862c88ace02329c2c9c31dd9532f814a07f9a7574'


def need(condition, message):
    if not condition:
        raise ValueError(message)


def digest(data):
    return hashlib.sha256(data).hexdigest()


def sha(path):
    with Path(path).open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()


def encoded(value):
    return (json.dumps(value, indent=2, sort_keys=True, allow_nan=False) + '\n').encode()


def write_new(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open('xb') as stream:
        stream.write(data)


def git(*args, cwd=ROOT):
    return subprocess.run(['git', *args], cwd=cwd, check=True, capture_output=True).stdout


def relative(path):
    path = Path(path).resolve(strict=True)
    need(path.is_relative_to(ROOT), 'Package inputs must be inside the matching checkout')
    return path.relative_to(ROOT)


def source_paths():
    paths = set()
    for folder in JAVA_ROOTS:
        paths.update(p.relative_to(ROOT) for p in (ROOT / PHASE / folder).rglob('*.java'))
    for folder in PYTHON_ROOTS:
        paths.update(p.relative_to(ROOT) for p in (ROOT / PHASE / folder).glob('*.py'))
    return sorted(paths)


def metadata_paths():
    names = (
        'EXECPLAN.md', 'benchmark/FIXTURE.md', 'benchmark/PROTOCOL.md',
        'benchmark/fixture-oracles-v1.json', 'contracts/GROWTH-CONTRACTS.md',
        'contracts/contract-seal-v1.json', 'recovery/READINESS.md',
        'recovery/input-survival-v1.json', 'recovery/root-baseline-class-comparison-v1.json',
        'recovery/preservation-helper-provenance-v1.json',
        'recovery/root-offline-v1/command.json', 'recovery/root-online-v1/command.json',
        'artifacts/SOURCE-DELIVERY-README.template.md', 'artifacts/PACKAGING.md',
    )
    paths = {PHASE / name for name in names if (ROOT / PHASE / name).is_file()}
    patterns = (
        'contracts/validation/*/receipt.json', 'contracts/validation/*/tests-command.json',
        'contracts/validation/*/compile-command.json',
        'contracts/validation/*/surefire-reports/TEST-*.xml',
        'contracts/validation/red-*/inputs.json',
        'runtime-*/compile-receipt.json', 'runtime-*/class-files.json', 'runtime-*/classpath.txt',
        'benchmark/runtime-*/compile-receipt.json', 'benchmark/runtime-*/class-files.json',
        'benchmark/runtime-*/classpath.txt', 'benchmark/runtime-*/inputs.json',
        'benchmark/qualification/*/pilot-validation.json',
        'benchmark/qualification/*/process.json', 'benchmark/qualification/*/command.json',
        'benchmark/checks/*.json', 'benchmark/checks/profile-rejection-v1/**/*',
        'reviews/*.md', 'reviews/*.json',
        'formatting/*/comparison.json', 'formatting/*/applied.json',
    )
    for pattern in patterns:
        paths.update(p.relative_to(ROOT) for p in (ROOT / PHASE).glob(pattern) if p.is_file())
    paths.update((Path('AGENTS.md'), Path('PLANS.md'), Path('.agent/PLANS.md')))
    paths.update((PRIOR_MANIFEST, OLD / 'artifacts/source-delivery-verification-v2.json',
                  OLD / 'artifacts/complete-source-v2.README.md'))
    return sorted(paths)


def no_primary(cohort):
    need(cohort.is_dir() and (cohort / 'protocol.json').is_file(), 'Use an existing frozen cohort')
    need(not list((cohort / 'claims').glob('*')), 'Timing has started; packaging must stay idle')


def prior_payloads():
    archive = ROOT / PRIOR_ARCHIVE
    need(sha(archive) == PRIOR_ARCHIVE_SHA, 'Historical complete source archive changed')
    manifest_data = (ROOT / PRIOR_MANIFEST).read_bytes()
    need(digest(manifest_data) == PRIOR_MANIFEST_SHA, 'Historical source manifest changed')
    manifest = json.loads(manifest_data)
    recovered = {}
    with tarfile.open(archive, 'r:gz') as stream:
        for member in stream.getmembers():
            path = PurePosixPath(member.name)
            need(member.isfile() and not path.is_absolute() and '..' not in path.parts
                 and path.parts[0] == manifest['archiveRoot'], 'Unsafe historical source member')
            name = PurePosixPath(*path.parts[1:]).as_posix()
            need(name and name not in recovered, 'Duplicate historical source member')
            recovered[name] = stream.extractfile(member).read()
    need(recovered.pop('MANIFEST.json') == manifest_data, 'Embedded historical manifest differs')
    need(set(recovered) == {entry['path'] for entry in manifest['files']}, 'Historical member set differs')
    for entry in manifest['files']:
        data = recovered[entry['path']]
        need(len(data) == entry['bytes'] and digest(data) == entry['sha256'], 'Historical payload mismatch')
        if entry['path'].endswith(('.java', '.py')):
            source = ROOT / entry['origin']
            need(source.is_file() and source.read_bytes() == data, 'Historical live source changed: ' + str(source))
    selected = {name: data for name, data in recovered.items()
                if not name.startswith('core/') and '/' in name}
    return selected


def inventory(args):
    need((args.protocol is None) == (args.qualification is None), 'Supply both final bindings or neither')
    paths = set(source_paths()) | set(metadata_paths())
    bindings = {}
    if args.protocol is not None:
        protocol_file, qualification_file = args.protocol.resolve(strict=True), args.qualification.resolve(strict=True)
        no_primary(protocol_file.parent)
        protocol = json.loads(protocol_file.read_text())
        qualification = json.loads(qualification_file.read_text())
        need(Path(protocol['qualificationFile']).resolve() == qualification_file, 'Wrong qualification binding')
        need(qualification['qualifiedForTiming'] is True and qualification['comparisonSamples'] == 0,
             'Final runtime is not qualified before timing')
        need(sha(protocol_file) == (protocol_file.parent / 'protocol.sha256').read_text().strip(),
             'Protocol seal differs')
        definitions = Path(protocol['fixtureDefinitionsFile']).resolve(strict=True)
        need(sha(definitions) == protocol['fixtureDefinitionsSha256'], 'Fixture definitions changed')
        paths.update(relative(p) for p in (protocol_file, qualification_file, definitions,
                                          protocol_file.parent / 'protocol.sha256'))
        bindings = {'protocol': str(protocol_file), 'protocolSha256': sha(protocol_file),
                    'qualification': str(qualification_file), 'qualificationSha256': sha(qualification_file)}
    entries = []
    for path in sorted(paths):
        data = (ROOT / path).read_bytes()
        entries.append({'path': path.as_posix(), 'bytes': len(data), 'sha256': digest(data)})
    result = {'format': 'growth-source-inventory-v1', 'createdUtc': datetime.now(timezone.utc).isoformat(),
              'readyToBuild': bool(bindings), 'baseCommit': BASE_COMMIT, **bindings,
              'builderSha256': sha(Path(__file__)), 'javaRoots': JAVA_ROOTS, 'pythonRoots': PYTHON_ROOTS,
              'canonicalSourcePaths': [p.as_posix() for p in source_paths()], 'files': entries,
              'predecessorArchive': {'path': PRIOR_ARCHIVE.as_posix(), 'sha256': PRIOR_ARCHIVE_SHA},
              'predecessorManifest': {'path': PRIOR_MANIFEST.as_posix(), 'sha256': PRIOR_MANIFEST_SHA},
              'compiledRuntimeIncluded': False, 'primaryMeasurementsIncluded': False,
              'provisional': not bool(bindings)}
    output = args.output.resolve()
    need(output.is_relative_to(ARTIFACTS), 'Keep source inventories in the growth artifacts directory')
    write_new(output, encoded(result))
    print(json.dumps({'inventory': str(output), 'sha256': sha(output), 'files': len(entries),
                      'readyToBuild': result['readyToBuild']}))


def difference(path, before, after, new_file=False):
    name = path.as_posix()
    header = f'diff --git a/{name} b/{name}\n' + ('new file mode 100644\n' if new_file else '')
    hunks = ''.join(difflib.unified_diff(before.decode().splitlines(keepends=True),
        after.decode().splitlines(keepends=True), fromfile='/dev/null' if new_file else 'a/' + name,
        tofile='b/' + name, n=3))
    need(bool(hunks), 'Expected a changed feature file: ' + name)
    return (header + hunks).encode()


def build(args):
    need(args.pretime_slot_granted, 'Coordinator must release a pre-timing packaging slot')
    selection_file = args.selection.resolve(strict=True)
    need(sha(selection_file) == args.approved_selection_sha256, 'Approved source inventory changed')
    selection = json.loads(selection_file.read_text())
    need(selection['format'] == 'growth-source-inventory-v1' and selection['readyToBuild']
         and not selection['provisional'], 'A provisional inventory cannot build an archive')
    need(selection['baseCommit'] == BASE_COMMIT and selection['builderSha256'] == sha(Path(__file__)),
         'Builder or patch base changed after selection')
    need(selection['canonicalSourcePaths'] == [p.as_posix() for p in source_paths()],
         'Canonical source set changed after selection')
    protocol_file = Path(selection['protocol'])
    qualification_file = Path(selection['qualification'])
    need(selection['protocolSha256'] == args.protocol_sha256 and sha(protocol_file) == args.protocol_sha256,
         'Coordinator protocol binding differs')
    need(selection['qualificationSha256'] == args.qualification_sha256
         and sha(qualification_file) == args.qualification_sha256, 'Coordinator qualification binding differs')
    cohort = protocol_file.parent
    no_primary(cohort)
    outputs = {key: ARTIFACTS / name for key, name in {
        'archive': 'complete-source-v1.tar.gz', 'manifest': 'complete-source-v1.manifest.json',
        'patch': 'complete-native-value-memo.patch', 'growthOnlyPatch': 'growth-only-versus-admission.patch',
        'readme': 'complete-source-v1.README.md', 'receipt': 'source-delivery-verification-v1.json',
        'readback': 'source-readback-v1'}.items()}
    need(not any(path.exists() for path in outputs.values()), 'Preserve previous artifacts; use a new version')
    checkout_commit = git('rev-parse', 'HEAD').decode().strip()
    branch = git('branch', '--show-current').decode().strip()
    payloads = prior_payloads()
    origins = {name: 'verified historical archive: ' + PRIOR_ARCHIVE.as_posix() for name in payloads}
    input_hashes = {PRIOR_ARCHIVE.as_posix(): PRIOR_ARCHIVE_SHA}
    for entry in selection['files']:
        path = Path(entry['path'])
        need(not path.is_absolute() and '..' not in path.parts, 'Unsafe selected path')
        data = (ROOT / path).read_bytes()
        need(len(data) == entry['bytes'] and digest(data) == entry['sha256'], 'Selected input changed: ' + str(path))
        name = path.as_posix()
        if name in payloads:
            need(payloads[name] == data, 'Historical and live payload conflict: ' + name)
        payloads[name], origins[name] = data, name
        input_hashes[name] = digest(data)
    selection_name = relative(selection_file).as_posix()
    payloads[selection_name], origins[selection_name] = selection_file.read_bytes(), selection_name
    input_hashes[selection_name] = sha(selection_file)
    helper_path = ROOT / RETENTION / 'artifacts/build_source_delivery.py'
    need(payloads[helper_path.relative_to(ROOT).as_posix()] == helper_path.read_bytes(),
         'Strict patch reader differs from supplied predecessor source')
    sys.dont_write_bytecode = True
    spec = importlib.util.spec_from_file_location('strict_growth_patch_reader', helper_path)
    helper = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(helper)
    production_paths = [PRODUCTION / (name + '.java') for name in NAMES]
    tracked = set(git('ls-tree', '-r', '--name-only', BASE_COMMIT, '--',
                      *map(str, production_paths)).decode().splitlines())
    bases, targets, production, sections = {}, {}, {}, []
    for path in production_paths:
        source = PHASE / 'implementation-src' / PACKAGE / path.name
        target = (ROOT / source).read_bytes()
        need(b'http://www.eclipse.org/org/documents/edl-v10.php.' in target.split(b'package ', 1)[0],
             'Canonical Java header differs: ' + str(source))
        existing = path.as_posix() in tracked
        before = git('show', BASE_COMMIT + ':' + path.as_posix()) if existing else b''
        need((ROOT / path).exists() == existing and (not existing or (ROOT / path).read_bytes() == before),
             'Production checkout differs from immutable patch base')
        bases[path.as_posix()], targets[path.as_posix()] = before, target
        sections.append(difference(path, before, target, new_file=not existing))
        payloads[path.as_posix()], origins[path.as_posix()] = target, source.as_posix()
        production[path.as_posix()] = {'canonicalSource': source.as_posix(), 'newFile': not existing,
                                     'beforeSha256': digest(before), 'afterSha256': digest(target)}
    patch = b''.join(sections)
    need(helper.apply_in_memory(patch.decode(), bases) == targets, 'Strict full patch reconstruction failed')
    memo_path = PRODUCTION / 'NativeDirectValueMemo.java'
    old_memo = (ROOT / OLD / 'implementation-src' / PACKAGE / memo_path.name).read_bytes()
    growth_patch = difference(memo_path, old_memo, targets[memo_path.as_posix()])
    need(helper.apply_in_memory(growth_patch.decode(), {memo_path.as_posix(): old_memo}) ==
         {memo_path.as_posix(): targets[memo_path.as_posix()]}, 'Strict growth patch reconstruction failed')
    write_new(outputs['patch'], patch)
    write_new(outputs['growthOnlyPatch'], growth_patch)
    disposable = Path(tempfile.mkdtemp(prefix='growth-source-patch-check-v1-', dir=ROOT.parent))
    for name, data in bases.items():
        if name in tracked:
            write_new(disposable / name, data)
    commands = []
    for directory, patch_file, before_map, after_map in (
            (disposable, outputs['patch'], None, targets),
            (disposable / 'admission-base', outputs['growthOnlyPatch'],
             {memo_path.as_posix(): old_memo}, {memo_path.as_posix(): targets[memo_path.as_posix()]})):
        if before_map:
            for name, data in before_map.items():
                write_new(directory / name, data)
        for check_only in (True, False):
            command = ['git', 'apply', *(['--check'] if check_only else []),
                       '--whitespace=error-all', str(patch_file)]
            result = subprocess.run(command, cwd=directory, capture_output=True, text=True)
            need(result.returncode == 0, 'Disposable patch applicability failed: ' + result.stderr)
            commands.append({'command': command, 'cwd': str(directory), 'exitCode': result.returncode,
                             'stdout': result.stdout, 'stderr': result.stderr})
        need({name: (directory / name).read_bytes() for name in after_map} == after_map,
             'Applied patch does not reconstruct complete canonical source')
    for key in ('patch', 'growthOnlyPatch'):
        payloads[outputs[key].name], origins[outputs[key].name] = outputs[key].read_bytes(), 'generated strict source diff'
    protocol, qualification = json.loads(protocol_file.read_text()), json.loads(qualification_file.read_text())
    template = (ARTIFACTS / 'SOURCE-DELIVERY-README.template.md').read_text()
    values = {'BASE_COMMIT': BASE_COMMIT, 'CHECKOUT_COMMIT': checkout_commit, 'BRANCH': branch,
              'PROTOCOL_SHA': args.protocol_sha256, 'QUALIFICATION_SHA': args.qualification_sha256,
              'ARCHIVE_ROOT': PREFIX, 'JVM_TOTAL': str(len(protocol['schedule'])),
              'WARMUPS': str(protocol['warmups']), 'MEASUREMENTS': str(protocol['measurements']),
              'TEST_EXECUTIONS': str(qualification['ownership']['qualifiedExecutions']),
              'EXACT_QUERIES': str(qualification['exactQueryExecutions'])}
    for key, value in values.items():
        template = template.replace('@' + key + '@', value)
    need(not __import__('re').search(r'@[A-Z_]+@', template), 'Unexpanded README field')
    readme = template.encode()
    write_new(outputs['readme'], readme)
    payloads['README.md'], origins['README.md'] = readme, 'generated reproduction guide'
    manifest = {'format': 1, 'archiveRoot': PREFIX, 'baseCommit': BASE_COMMIT, 'branch': branch,
        'checkoutCommitAtPackagingStart': checkout_commit, 'standaloneDistribution': False,
        'compiledRuntimeIncluded': False, 'primaryMeasurementsIncluded': False,
        'frozenProtocolSha256': args.protocol_sha256, 'qualificationSha256': args.qualification_sha256,
        'sourceInventory': {'path': selection_name, 'sha256': sha(selection_file)},
        'predecessorArchive': {'path': PRIOR_ARCHIVE.as_posix(), 'sha256': PRIOR_ARCHIVE_SHA},
        'productionFiles': production, 'growthOnlyBaseSha256': digest(old_memo),
        'historicalPayloadScope': 'Verified predecessor sources and provenance; no predecessor timings are pooled.',
        'manifestSelfEntryOmitted': 'External verification receipt hashes the manifest; every other member is listed.',
        'files': [{'path': name, 'bytes': len(data), 'sha256': digest(data), 'origin': origins[name]}
                  for name, data in sorted(payloads.items())]}
    manifest_bytes = encoded(manifest)
    write_new(outputs['manifest'], manifest_bytes)
    members = {**payloads, 'MANIFEST.json': manifest_bytes}
    buffer = io.BytesIO()
    with tarfile.open(fileobj=buffer, mode='w', format=tarfile.PAX_FORMAT) as archive:
        for name, data in sorted(members.items()):
            path = PurePosixPath(name)
            need(not path.is_absolute() and '..' not in path.parts, 'Unsafe generated member')
            info = tarfile.TarInfo(PREFIX + '/' + name)
            info.size, info.mode, info.mtime = len(data), 0o644, 0
            info.uid = info.gid = 0
            archive.addfile(info, io.BytesIO(data))
    no_primary(cohort)
    write_new(outputs['archive'], gzip.compress(buffer.getvalue(), compresslevel=6, mtime=0))
    recovered = {}
    with tarfile.open(outputs['archive'], 'r:gz') as archive:
        for member in archive.getmembers():
            path = PurePosixPath(member.name)
            need(member.isfile() and not path.is_absolute() and '..' not in path.parts
                 and path.parts[0] == PREFIX, 'Unsafe/nonregular generated member')
            name = PurePosixPath(*path.parts[1:]).as_posix()
            need(name and name not in recovered, 'Duplicate generated member')
            target = outputs['readback'] / member.name
            write_new(target, archive.extractfile(member).read())
            recovered[name] = target.read_bytes()
    need(recovered == members, 'Complete archive readback differs')
    for entry in manifest['files']:
        data = recovered[entry['path']]
        need(len(data) == entry['bytes'] and digest(data) == entry['sha256'], 'Readback manifest differs')
    need(helper.apply_in_memory(recovered[outputs['patch'].name].decode(), bases) == targets,
         'Archived full patch differs')
    need(all(sha(ROOT / name) == expected for name, expected in input_hashes.items()),
         'Input changed during packaging')
    need(git('rev-parse', 'HEAD').decode().strip() == checkout_commit, 'Checkout moved during packaging')
    no_primary(cohort)
    def record(path):
        return {'file': path.name, 'bytes': path.stat().st_size, 'sha256': sha(path)}
    receipt = {'verified': True, 'baseCommit': BASE_COMMIT, 'checkoutCommitAtPackagingStart': checkout_commit,
        'frozenProtocolSha256': args.protocol_sha256, 'qualificationSha256': args.qualification_sha256,
        **{key: record(outputs[key]) for key in ('archive', 'manifest', 'patch', 'growthOnlyPatch', 'readme')},
        'archiveRegularFiles': len(members), 'manifestPayloadFiles': len(payloads),
        'uncompressedPayloadBytes': sum(len(data) for data in members.values()),
        'javaSources': sum(name.endswith('.java') for name in members),
        'pythonSources': sum(name.endswith('.py') for name in members),
        'productionFilesReconstructedExactly': 4, 'strictInMemoryReconstruction': True,
        'patchApplications': commands, 'disposableAppliedFilesMatchCanonical': True,
        'growthOnlyPatchCheckedAndReconstructed': True, 'originalSourceInputsUnchanged': True,
        'repositoryModuleFilesModified': False, 'javaCommandsRun': 0, 'primaryClaimsAtCompletion': 0,
        'readbackDirectory': str(outputs['readback']), 'disposableBaseDirectory': str(disposable),
        'builderSha256': sha(Path(__file__))}
    write_new(outputs['receipt'], encoded(receipt))
    print(json.dumps(receipt, indent=2, sort_keys=True))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest='command', required=True)
    choose = commands.add_parser('inventory')
    choose.add_argument('--output', type=Path, required=True)
    choose.add_argument('--protocol', type=Path)
    choose.add_argument('--qualification', type=Path)
    package = commands.add_parser('build')
    package.add_argument('--selection', type=Path, required=True)
    package.add_argument('--approved-selection-sha256', required=True)
    package.add_argument('--protocol-sha256', required=True)
    package.add_argument('--qualification-sha256', required=True)
    package.add_argument('--pretime-slot-granted', action='store_true')
    args = parser.parse_args()
    inventory(args) if args.command == 'inventory' else build(args)


if __name__ == '__main__':
    main()
